import std.io

pub type AppError = Failed(String)

let ns: List<Int64> = [10, 20, 30, 40]

fn churn() -> Int64 {
    var i: Int64 = 0
    while i < 80000 {
        let xs: List<Int64> = []
        let z: Int64 = i
        i = z + 1
    }
    return i
}

pub fn main() effect io -> Result<(), AppError> {
    let n = churn()
    let probe: List<Int64> = [7, 7, 7, 7]
    var s: Int64 = 0
    for x in ns {
        s = s + x
    }
    var p: Int64 = 0
    for y in probe {
        p = p + y
    }
    io.println("${s} ${p} ${n}")
    return Ok(())
}
